export const defaults=()=>({version:1,age:null,interests:[],completed:{},attempts:{},bookmarks:[],notes:{},xp:0,goal:3,reduced:false,last:null,lastTopic:null,visits:[],level:{},course:{},focus:{minutes:25,breakMinutes:5,sessions:[]}});
export function normalizeState(data){const d=defaults();if(!data||typeof data!=='object')return d;const ages=['primary','middle','secondary','advanced'],subjects=['math','science','coding','cs','engineering','logic'];const valid=k=>typeof k==='string'&&ages.includes(k.split(':')[0])&&subjects.includes(k.split(':')[1]);d.age=ages.includes(data.age)?data.age:null;d.interests=Array.isArray(data.interests)?data.interests.filter(x=>subjects.includes(x)):[];for(const [k,v]of Object.entries(data.completed||{})){if(valid(k)&&v&&Number.isFinite(Date.parse(v.date)))d.completed[k]={date:v.date,assisted:!!v.assisted}}for(const [k,v]of Object.entries(data.attempts||{})){if(valid(k)&&v&&Number.isFinite(v.tries)&&v.tries>=0)d.attempts[k]={tries:v.tries,correct:Math.max(0,Math.min(v.tries,Number(v.correct)||0)),hints:Math.max(0,Number(v.hints)||0)}}d.bookmarks=Array.isArray(data.bookmarks)?[...new Set(data.bookmarks.filter(valid))]:[];for(const[k,v]of Object.entries(data.notes||{}))if(valid(k)&&typeof v==='string')d.notes[k]=v.slice(0,20000);d.xp=Object.values(d.completed).reduce((sum,v)=>sum+(v.assisted?30:50),0);d.goal=Math.max(1,Math.min(12,Number(data.goal)||3));d.reduced=!!data.reduced;d.last=subjects.includes(data.last)?data.last:null;d.lastTopic=data.lastTopic&&ages.includes(data.lastTopic.age)&&subjects.includes(data.lastTopic.subject)&&Number.isInteger(data.lastTopic.index)&&data.lastTopic.index>=0&&data.lastTopic.index<6?{age:data.lastTopic.age,subject:data.lastTopic.subject,index:data.lastTopic.index}:null;d.visits=Array.isArray(data.visits)?[...new Set(data.visits.filter(v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)))]:[];d.level=data.level&&typeof data.level==='object'?Object.fromEntries(Object.entries(data.level).filter(([k,v])=>subjects.includes(k)&&['foundation','extension'].includes(v))):{};for(const[k,v]of Object.entries(data.course||{})){if(!valid(k)||!v||typeof v!=='object')continue;d.course[k]={stage:Math.max(0,Math.min(2,Number(v.stage)||0)),correct:Array.isArray(v.correct)?[...new Set(v.correct.filter(n=>Number.isInteger(n)&&n>=0&&n<=2))]:[],hints:Array.isArray(v.hints)?[...new Set(v.hints.filter(n=>Number.isInteger(n)&&n>=0&&n<=2))]:[],attempts:Object.fromEntries(Object.entries(v.attempts||{}).filter(([n,x])=>['0','1','2'].includes(n)&&Number.isInteger(x)&&x>=0)),level:Math.max(0,Math.min(2,Number(v.level)||0)),project:Object.fromEntries(['prediction','evidence','conclusion','savedAt'].map(n=>[n,typeof v.project?.[n]==='string'?v.project[n].slice(0,12000):'']))}}d.focus={minutes:Math.max(5,Math.min(90,Number(data.focus?.minutes)||25)),breakMinutes:Math.max(1,Math.min(30,Number(data.focus?.breakMinutes)||5)),sessions:Array.isArray(data.focus?.sessions)?data.focus.sessions.filter(x=>x&&typeof x.date==='string'&&Number.isFinite(Date.parse(x.date))&&Number.isFinite(x.minutes)).slice(-100).map(x=>({date:x.date,minutes:Math.max(0,Math.min(90,x.minutes))})):[]};return d}
export function readState(storage){try{return normalizeState(JSON.parse(storage.getItem('nexora-v1')||'{}'))}catch{return defaults()}}
export function complete(state,key,assisted=false){if(state.completed[key])return false;state.completed[key]={date:new Date().toISOString(),assisted};state.xp+=assisted?30:50;return true}
export function recordAttempt(state,key,correct,hinted){const a=state.attempts[key]||{tries:0,correct:0,hints:0};a.tries++;a.correct+=Number(correct);a.hints+=Number(hinted);state.attempts[key]=a;return a}
export function mastery(state,subject){const entries=Object.entries(state.attempts).filter(([k])=>k.split(':')[1]===subject&&(!state.age||k.split(':')[0]===state.age));if(!entries.length)return 0;return Math.round(entries.reduce((s,[,v])=>s+Math.min(1,v.correct/Math.max(1,v.tries))*(v.hints?0.8:1),0)/entries.length*100)}
export function result(model,value,mass=2){switch(model){case'fraction':return value/8;case'force':return value/mass;case'loop':return Array.from({length:value},(_,i)=>i);case'network':return value*3;case'control':return 2+0.5*(value-2);case'data':return (2+4+value)/3;default:throw Error('Unknown model')}}
